from produire import produire,paras,table,steps
from medicaments import amoxicilline
parts=[
('La pharyngite aiguë est une inflammation récente du pharynx, souvent associée à une amygdalite. Les {distinctions étiologiques} séparent cause virale, streptococcique et complication profonde.',paras('Le terme angine décrit un syndrome clinique et ne signifie pas automatiquement infection bactérienne. L’exsudat amygdalien peut se rencontrer dans des infections virales, notamment la mononucléose.')),
('La majorité des pharyngites de l’enfant est virale. Le {contexte épidémiologique} modifie la probabilité d’une infection à streptocoque du groupe A.',paras('Le streptocoque est plus fréquent chez l’enfant d’âge scolaire que chez le très jeune enfant. Le portage asymptomatique peut expliquer un test positif qui ne rend pas compte de tous les symptômes.')),
('L’inflammation provoque douleur et gêne à la déglutition. Les {mécanismes de complication} expliquent pourquoi une aggravation localisée nécessite un nouvel examen.',paras('Une infection peut se compliquer d’une suppuration périamygdalienne ou cervicale. Les complications immunologiques post-streptococciques sont distinctes de l’infection locale ; le risque de rhumatisme articulaire aigu dépend aussi du contexte individuel et épidémiologique.')),
('Rechercher d’abord une menace respiratoire et une infection profonde. Les {signes d’alarme} invalident une simple stratégie d’attente.',paras('Stridor, dyspnée, hypersialorrhée avec salive non avalée, trismus, voix étouffée, torticolis, tuméfaction cervicale ou sepsis imposent une prise en charge urgente. Une fièvre qui reprend après une amélioration, avec douleur cervicale et altération générale, fait notamment évoquer un syndrome de Lemierre.')),
('L’entretien précise fièvre, toux, rhinorrhée et capacité à boire. Les {facteurs de risque} déterminent la portée de l’observation.',paras('Rechercher immunodépression, antécédent personnel ou familial de rhumatisme articulaire aigu, séjour ou migration depuis une région à risque, exposition et évolution. Les recommandations pédiatriques suisses donnent un poids particulier à ces critères d’inquiétude.')),
('Examiner état général, hydratation, pharynx et cou. Les {signes locaux} doivent être interprétés ensemble.',paras('Décrire symétrie amygdalienne, exsudat, pétéchies palatines, adénopathies antérieures sensibles, rash et ouverture buccale. Un bombement unilatéral et une déviation de la luette orientent vers un abcès ; ne pas forcer l’examen en cas de menace respiratoire.')),
('Toux et rhinorrhée soutiennent une cause virale. Le {diagnostic différentiel} reste ouvert en cas de tableau atypique.',table(['Profil','Hypothèse'],[['Exsudat avec fatigue et adénopathies diffuses.','Mononucléose ; éviter une prescription aveugle d’amoxicilline.'],['Trismus et douleur unilatérale.','Abcès périamygdalien.'],['Ulcérations, gingivite ou lésions des mains et pieds.','Herpès ou infection à entérovirus selon la distribution.'],['Membrane adhérente et exposition compatible.','Évaluation urgente, notamment pour diphtérie selon vaccination et voyage.']])) ,
('Le score de Centor estime une probabilité et ne prouve pas le diagnostic. Les {quatre critères} ne sont utilisés qu’après exclusion des urgences.',paras('Attribuer un point pour absence de toux, exsudat amygdalien, fièvre rapportée ou température supérieure à 38 °C, et adénopathie cervicale antérieure sensible. Le score de McIsaac ajoute une pondération liée à l’âge ; ne pas mélanger les deux scores.')),
('Le test rapide est utile si son résultat change la décision. Les {indications suisses du test} évitent un dépistage systématique sans bénéfice.',paras('La SSI ne recommande pas de frottis pour un score de Centor de 0 à 2 dans le cadre usuel. Pour un score de 3 à 4, envisager le test si une antibiothérapie est envisagée.', 'Chez l’enfant sans critère inquiétant, Pédiatrie suisse propose soins symptomatiques et réévaluation à 48–72 heures, sans test systématique. Un antécédent de rhumatisme articulaire aigu justifie une stratégie particulière ; les signes de complication priment sur le score. La culture de confirmation systématique après test rapide négatif n’est plus recommandée dans cette stratégie.')),
('La {décision thérapeutique} combine gravité, terrain et suivi. Un test positif ne rend pas les antibiotiques obligatoires dans toutes les situations.',steps('Écarter urgence et complication, puis apprécier les facteurs individuels de risque.', 'Si tableau simple sans inquiétude, proposer traitement symptomatique et suivi, avec réévaluation pédiatrique à 48–72 heures.', 'Si un antibiotique est envisagé, utiliser le test dans la stratégie adaptée ; choisir le schéma selon recommandation suisse, produit et patient.', 'Réexaminer plus tôt si aggravation, impossibilité de boire, gêne respiratoire ou signe focal.')),
('La prise en charge associe hydratation, soulagement de la douleur et surveillance. Les {modalités médicamenteuses} distinguent recommandation et notice du produit.',paras('La SSI autorise l’observation sans antibiotique, y compris dans certaines pharyngites streptococciques. Une complication suppurée exige une autre filière thérapeutique.', '@@MEDICAMENTS@@')),
('Les {conseils de prévention} comprennent hygiène des mains et limitation des contacts avec les sécrétions. Le retour à l’école dépend de l’état général selon les recommandations suisses citées.',paras('Ne pas prescrire un antibiotique uniquement pour permettre le retour à l’école. Donner des consignes écrites de reconsultation ; vérifier que la famille peut organiser le suivi.')),
('Un exsudat ne prouve pas une infection bactérienne. Centor oriente une stratégie, sans remplacer le tri des urgences. Le suivi permet de limiter les antibiotiques sans banaliser une aggravation.','')]
quiz=[('Le mot angine signifie-t-il streptocoque ?','Non : il décrit un syndrome.'),('L’exsudat exclut-il un virus ?','Non, notamment en cas de mononucléose.'),('Centor vaut-il un diagnostic microbiologique ?','Non : il estime une probabilité.'),('Combien de critères comprend Centor ?','Quatre : absence de toux, exsudat, fièvre et adénopathie antérieure sensible.'),('Faut-il tester systématiquement un enfant bien portant sans critère inquiétant ?','Non : soins symptomatiques et suivi sont possibles selon les recommandations suisses.'),('Quel délai de suivi pédiatrique est proposé ?','48 à 72 heures, plus tôt si aggravation.'),('Un test positif exige-t-il toujours un antibiotique ?','Non : la décision dépend du contexte et des critères inquiétants.'),('Le score rassure-t-il devant un stridor ?','Non : le problème respiratoire est prioritaire.'),('Que suggèrent trismus et douleur unilatérale ?','Une complication périamygdalienne ou profonde.'),('Faut-il systématiquement cultiver après un test rapide négatif ?','Non dans la stratégie suisse citée ; réévaluer le syndrome si nécessaire.'),('Le risque de rhumatisme articulaire aigu est-il identique pour tous ?','Non : antécédents et contexte épidémiologique comptent.'),('La durée SSI est-elle identique au texte Amoxi-Mepha ?','Non : six jours dans la directive contre au moins dix jours pour les streptocoques dans la notice.'),('L’amoxicilline est-elle indiquée dans une mononucléose ?','Non : la préparation citée la contre-indique, avec risque d’exanthème.'),('Une reprise fébrile avec douleur cervicale peut-elle attendre ?','Non : rechercher une infection profonde ou un syndrome de Lemierre.')]
produire(1,parts,quiz,(3,4,5,19),amoxicilline)
